def _deterministic_prepass(
    runner: Runner,
    paths: list[str],
    *,
    cwd: str | None,
) -> list[str]:
    remaining: list[str] = []
    for path in paths:
        base = Path(path).name
        if base == "plugin.json" and _is_plugin_json_path(path):
            result = git.checkout_ours(runner, path, cwd=cwd)
            if result.returncode == 0:
                _ = git.add(runner, path, cwd=cwd)
            else:
                remaining.append(path)
            continue
        if base in ("version.go", "go.sum"):
            result = git.checkout_ours(runner, path, cwd=cwd)
            if result.returncode == 0:
                _ = git.add(runner, path, cwd=cwd)
            else:
                remaining.append(path)
            continue
        remaining.append(path)
    return remaining


def _unmerged_paths(runner: Runner, *, cwd: str | None) -> list[str]:
    try:
        return git.unmerged_paths(runner, cwd=cwd)
    except ShipError:
        raise Stalled(_redact_outbound("git diff --diff-filter=U failed")) from None


def make_conflict_launch_fn(
    runner: Runner,
    *,
    repo: str,
    run_id: str,
    output_dir: str | Path,
    cwd: str | None = None,
) -> ConflictLaunchFn:
    """Build a fixer launch_fn using ``build_launch_argv`` / ``launch_tier`` parity."""
    out_root = Path(output_dir)
    out_root.mkdir(parents=True, exist_ok=True)
    seen_token_records: set[str] = set()

    def launch(tier: str, conflict_csv: str) -> agents.TierAttempt:
        output = out_root / f"conflict-{tier}.out"
        failure_log = out_root / f"conflict-{tier}.fail.log"
        if tier in {"codex", "cursor"}:
            Path(f"{output}.token-record").unlink(missing_ok=True)
        result = agents.launch_tier(
            runner,
            tier,
            role=config.FIXER_ROLE,
            output=str(output),
            run_id=run_id,
            repo=repo,
            conflict_files=conflict_csv,
            cwd=cwd,
        )
        if tier in {"codex", "cursor"}:
            implement_tmpdir = os.environ.get(config.ENV_IMPLEMENT_TMPDIR)
            _ = agents.ingest_launcher_token_sidecar(
                runner,
                launcher_stdout=result.stdout + result.stderr,
                output=output,
                tmpdir=implement_tmpdir,
                implement_tmpdir=implement_tmpdir,
                seen=seen_token_records,
                cwd=cwd,
                allow_output_fallback=True,
            )
        launcher_exit = agents.resolve_launcher_exit(
            result.stdout + result.stderr,
            output_file=output,
            process_rc=result.returncode,
        )
        failure = agents.classify_launch_failure(
            launcher_exit,
            failure_log if failure_log.is_file() else None,
            tool=tier,
            output_file=output,
        )
        flog: str | Path | None = failure_log if failure_log.is_file() else None
        return agents.TierAttempt(
            tier=tier,
            wrapper_rc=result.returncode,
            launcher_exit=launcher_exit,
            failure=failure,
            failure_log=flog,
        )

    return launch


def _resolve_conflicts(
    runner: Runner,
    launch_fn: ConflictLaunchFn,
    *,
    repo: str,
    run_id: str,
    cwd: str | None,
    tmpdir: str | None = None,
    enable_pre_push_handoff: bool = False,
) -> None:
    _ = repo, run_id
    while True:
        unmerged = _unmerged_paths(runner, cwd=cwd)
        if unmerged:
            remaining = _deterministic_prepass(runner, unmerged, cwd=cwd)
            if remaining:
                conflict_csv = ",".join(remaining)

                def _tier_launch(tier: str, csv: str = conflict_csv) -> agents.TierAttempt:
                    return launch_fn(tier, csv)

                waterfall = agents.run_waterfall(
                    config.FIXER_TIER_ORDER,
                    _tier_launch,
                    runner=runner,
                    cwd=cwd,
                )
                if waterfall.winning_tier is None:
                    conflict_files = tuple(remaining)
                    if enable_pre_push_handoff and _conflicts_are_non_bump_only(conflict_files):
                        _write_handoff_flag(tmpdir)
                        raise PrePushConflictHandoff(
                            conflict_files=conflict_files,
                            resume_phase=config.SHIP_PR_RRR_RESUME_PHASE,
                            caller_kind=config.SHIP_PR_PRE_PUSH_CALLER_KIND,
                        )
                    raise Stalled(
                        _redact_outbound("fixer waterfall could not resolve conflicts"),
                    )
                unmerged_remaining = _unmerged_paths(runner, cwd=cwd)
                if unmerged_remaining:
                    conflict_files = tuple(unmerged_remaining)
                    if enable_pre_push_handoff and _conflicts_are_non_bump_only(conflict_files):
                        _write_handoff_flag(tmpdir)
                        raise PrePushConflictHandoff(
                            conflict_files=conflict_files,
                            resume_phase=config.SHIP_PR_RRR_RESUME_PHASE,
                            caller_kind=config.SHIP_PR_PRE_PUSH_CALLER_KIND,
                        )
                    raise Stalled(_redact_outbound("conflicts remain after fixer waterfall"))

        continue_result = git.rebase_continue(runner, cwd=cwd)
        if continue_result.returncode == 0:
            if _unmerged_paths(runner, cwd=cwd):
                continue
            return

        unmerged_after = _unmerged_paths(runner, cwd=cwd)
        combined = f"{continue_result.stdout}\n{continue_result.stderr}"
        if unmerged_after:
            continue

        _promote_inner_done(output)
    _emit_kv("LAUNCHER_EXIT", launcher_exit)
    _emit_kv("OUTPUT", str(output))
    return 0


def _validate_ci_args(args: argparse.Namespace) -> tuple[bool, int]:
    if args.role not in {"fix", "resolve-conflict"}:
        _err("agent launch-ci: --role must be fix or resolve-conflict")
        return False, 2
    if not _is_positive_int(args.timeout):
        _err("agent launch-ci: --timeout must be a positive integer")
        return False, 2
    if not Path(args.output).is_absolute() or not _validate_meta_path("--output", args.output):
        return False, 2
    if args.plan_file and not Path(args.plan_file).is_absolute():
        _err("agent launch-ci: --plan-file must be an absolute path")
        return False, 2
    if args.failure_log:
        ok, msg = _validate_failure_log_path(Path(args.failure_log))
        if not ok:
            _err(f"agent launch-ci: {msg}")
            return False, 2
    if args.conflict_files:
        ok, msg = _validate_conflict_files_csv(args.conflict_files)
        if not ok:
            _err(f"agent launch-ci: {msg}")
            return False, 2
    return True, 0


def _validate_conflict_files_csv(value: str) -> tuple[bool, str]:
    if _CTRL_RE.search(value):
        return False, "conflict files must not contain control characters"
    for item in value.split(","):
        if not item:
            return False, "conflict files must not contain empty entries"
        if "//" in item:
            return False, "conflict files must be normalized repo-relative paths"
        if not re.fullmatch(r"[A-Za-z0-9._/-]+", item):
            return False, "unsupported characters in conflict files"
        path = Path(item)
        if path.is_absolute() or ".." in path.parts or "." in path.parts:
            return False, "conflict files must be safe repo-relative paths"
    return True, ""


def _validate_failure_log_path(path: Path) -> tuple[bool, str]:
    root_raw = os.environ.get("IMPLEMENT_TMPDIR", "")
    if not root_raw:
        return False, "--failure-log requires IMPLEMENT_TMPDIR"
    try:
        root = Path(root_raw).resolve(strict=True)
        if not root.is_dir() or root.is_symlink():
            return False, "IMPLEMENT_TMPDIR must resolve to a non-symlink directory"
        if not path.is_absolute() or path.is_symlink() or not path.is_file():
            return False, "--failure-log must be an absolute regular non-symlink file"
        canon = path.resolve(strict=True)
        if not _under(canon, root):
            return False, "--failure-log must resolve under IMPLEMENT_TMPDIR"
        if canon.stat().st_size > 1024 * 1024:
            return False, "--failure-log exceeds 1 MB"
    except OSError:
        return False, "--failure-log validation failed"
    return True, ""


